"use strict";

const ADD_WASM_BYTES = new Uint8Array([
  0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
  0x01, 0x07, 0x01, 0x60, 0x02, 0x7f, 0x7f, 0x01,
  0x7f, 0x03, 0x02, 0x01, 0x00, 0x07, 0x07, 0x01,
  0x03, 0x61, 0x64, 0x64, 0x00, 0x00, 0x0a, 0x09,
  0x01, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a,
  0x0b,
]);

module.exports = async function add(left, right) {
  const valid = WebAssembly.validate(ADD_WASM_BYTES);
  const module = await WebAssembly.compile(ADD_WASM_BYTES);
  const instance = await WebAssembly.instantiate(module);
  return `wasm:v2/${instance.exports.add(left, right)}/${valid ? "valid" : "invalid"}`;
};
